(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c3-advanced-1"]={"id":"unit22-trap-c3-advanced-1","unitId":"2-2","chapterIds":["2-2"],"unitType":"advanced","group":"선지 변형 유형 · 순서","name":"심화 5지선다 1","level":"심화","desc":"2-2단원 · 순서","revision":1,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"순서","parts":[{"name":"U22-08 · 무료 공연과 입장권 배포","items":[{"paragraphCount":1,"readingLabel":"1문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 1문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 1문단]\n여름마다 뉴욕시의 퍼블릭 시어터는 센트럴 파크에서 셰익스피어 무료 야외 공연을 연다. 오후 1시부터 배포하는 저녁 공연 입장권을 받기 위해 사람들은 몇 시간 전부터 줄을 서기 시작한다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["순서"],"id":"U22-08-S1","type":"mc","sent":"1문단의 내용과 맞는 설명은?","options":["공연은 유료다.","저녁 공연 표는 공연 시작 직전부터 나누어 준다.","공연은 무료다. 오후 1시부터 저녁 공연 표를 나누어 준다. 사람들은 표를 받으려고 미리 줄을 선다.","사람들은 공연이 끝난 뒤에 표를 받으려고 줄을 선다.","나누어 주는 표는 오후 1시에 시작하는 공연의 표다."],"answer":"공연은 무료다. 오후 1시부터 저녁 공연 표를 나누어 준다. 사람들은 표를 받으려고 미리 줄을 선다.","why":"오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","choiceReviews":{"공연은 무료다. 오후 1시부터 저녁 공연 표를 나누어 준다. 사람들은 표를 받으려고 미리 줄을 선다.":{"reason":"오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","edits":[]},"공연은 유료다.":{"reason":"바르게 고치면: 공연은 무료다.\n오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","edits":[{"start":4,"end":8,"before":"유료다.","after":"무료다."}]},"저녁 공연 표는 공연 시작 직전부터 나누어 준다.":{"reason":"바르게 고치면: 저녁 공연 표는 오후 1시부터 나누어 준다.\n오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","edits":[{"start":9,"end":20,"before":"공연 시작 직전부터 ","after":"오후 1시부터 "}]},"사람들은 공연이 끝난 뒤에 표를 받으려고 줄을 선다.":{"reason":"바르게 고치면: 사람들은 표를 받으려고 미리 줄을 선다.\n오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","edits":[{"start":5,"end":15,"before":"공연이 끝난 뒤에 ","after":""},{"start":18,"end":23,"before":"받으려고 ","after":"받으려고 미리 "}]},"나누어 주는 표는 오후 1시에 시작하는 공연의 표다.":{"reason":"바르게 고치면: 나누어 주는 표는 저녁에 시작하는 공연의 표다.\n오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","edits":[{"start":10,"end":17,"before":"오후 1시에 ","after":"저녁에 "}]}},"pageSpecificReasons":true,"evidence":{"title":"무료 공연과 입장권 배포","statement":"공연은 무료다. 오후 1시부터 저녁 공연 표를 나누어 준다. 사람들은 표를 받으려고 미리 줄을 선다.","explanation":"오후 1시는 공연이 시작되는 시간이 아니라 표를 나누어 주기 시작하는 시간이에요. 표는 저녁에 열리는 무료 공연을 위한 것이에요.\n1문단에서 확인할 수 있어요.","valid":["L01:1","L01:2"],"sources":[{"id":"L01","title":"줄 서기를 돈으로 살 수 있을까","label":"1문단","sentences":[{"id":"L01:1","text":"여름마다 뉴욕시의 퍼블릭 시어터는 센트럴 파크에서 셰익스피어 무료 야외 공연을 연다.","paragraph":0,"memberIds":["L01:1"],"topic":"미국 뉴욕에는 여름마다 큰 공원에서 공짜 연극을 여는 극장이 있다. 연극은 셰익스피어의 작품이다."},{"id":"L01:2","text":"오후 1시부터 배포하는 저녁 공연 입장권을 받기 위해 사람들은 몇 시간 전부터 줄을 서기 시작한다.","paragraph":0,"memberIds":["L01:2"],"topic":"표는 오후 1시에 나눠 준다. 공연은 저녁이다. 표를 받으려고 사람들은 몇 시간 전부터 줄을 선다."}]}]},"editorSourceVersion":"7e66dc68efa9346217600b37fe46d4a0ea804ad7d38ee3fc0364db27fa3fb2dd"}]},{"name":"U22-24 · 줄 서기의 도덕성에 관한 질문","items":[{"paragraphCount":1,"readingLabel":"9문단","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 9문단","passage":"[줄 서기를 돈으로 살 수 있을까 · 9문단]\n그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까? 대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까? 센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다. “대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":true,"originPage":"unit22","skills":["순서"],"id":"U22-24-S1","type":"mc","sent":"9문단의 내용과 맞는 설명은?","options":["9문단은 줄 서기가 아니라 가격을 올렸을 때의 효과를 묻는다.","9문단은 대리 줄 서기와 암표 판매를 왜 허용하려 하는지 묻는다.","9문단은 이유를 묻지 않고 줄 서기에 관한 결론만 내린다.","9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","9문단 처음의 질문은 극장 대변인이 한 말이다."],"answer":"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","why":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","choiceReviews":{"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.":{"reason":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[]},"9문단은 줄 서기가 아니라 가격을 올렸을 때의 효과를 묻는다.":{"reason":"바르게 고치면: 9문단은 줄 서기가 도덕적으로 옳은지 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":11,"end":30,"before":"아니라 가격을 올렸을 때의 효과를 ","after":"도덕적으로 옳은지 "}]},"9문단은 대리 줄 서기와 암표 판매를 왜 허용하려 하는지 묻는다.":{"reason":"바르게 고치면: 9문단은 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":23,"end":28,"before":"허용하려 ","after":"막으려 "}]},"9문단은 이유를 묻지 않고 줄 서기에 관한 결론만 내린다.":{"reason":"바르게 고치면: 9문단은 줄 서기와 암표 판매에 관한 이유를 묻는다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":0,"end":5,"before":"9문단은 ","after":"9문단은 줄 서기와 암표 판매에 관한 "},{"start":9,"end":32,"before":"묻지 않고 줄 서기에 관한 결론만 내린다.","after":"묻는다."}]},"9문단 처음의 질문은 극장 대변인이 한 말이다.":{"reason":"바르게 고치면: 9문단 처음의 질문은 글쓴이가 한 말이다.\n9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","edits":[{"start":12,"end":20,"before":"극장 대변인이 ","after":"글쓴이가 "}]}},"pageSpecificReasons":true,"evidence":{"title":"줄 서기의 도덕성에 관한 질문","statement":"9문단은 줄 서기가 도덕적으로 옳은지 생각해 보게 한다. 대리 줄 서기와 암표 판매를 왜 막으려 하는지 묻는다.","explanation":"9문단 첫머리에서는 대리 줄 서기와 암표 판매를 막으려는 이유를 물어요. 대신 줄을 서거나 암표를 파는 일이 도덕적으로 옳은지도 따져 보려는 질문이에요.\n9문단에서 확인할 수 있어요.","valid":["L09:1","L09:2"],"sources":[{"id":"L09","title":"줄 서기를 돈으로 살 수 있을까","label":"9문단","sentences":[{"id":"L09:1","text":"그렇다면 줄 서기의 도덕성 측면에서는 어떤 주장을 펼칠 수 있을까?","paragraph":0,"memberIds":["L09:1"],"topic":"그럼 이제 반대로, 줄 서기가 옳다고 보는 쪽(줄 서기의 도덕성)에서는 무슨 말을 할 수 있을까?"},{"id":"L09:2","text":"대리 줄 서기와 암표 판매를 금지하려는 이유는 무엇일까?","paragraph":0,"memberIds":["L09:2"],"topic":"대신 줄 서기와 암표를 왜 막으려는 걸까?"},{"id":"L09:3","text":"센트럴 파크에서 열리는 셰익스피어 공연의 대변인은 다음과 같은 근거를 댔다.","paragraph":0,"memberIds":["L09:3"],"topic":"공연 측 대변인(대표로 말하는 사람)은 이렇게 말했다."},{"id":"L09:4","text":"“대리 줄 서기와 암표 판매는 공원에서 셰익스피어 공연을 간절하게 보고 싶어 하는 사람에게서 좌석과 입장권을 빼앗고 있다. 우리는 사람들이 공연을 무료로 관람하기를 원한다.”","paragraph":0,"memberIds":["L09:4","L09:5"],"topic":"\"대신 줄 서기와 암표는 공연을 정말 보고 싶은 사람의 자리를 빼앗는다."}]}]},"editorSourceVersion":"3ac7fa613e52a8d234c3388b4bd449dcb81adf8a78c69da5b9f62300eec34404"}]}]};})(window);
